sampler sampler_pw_noise_lq;
vec2 rs, rs0;
vec3 noise, ret1;

void main() {
  vec3 ret = vec3(0.0);
  vec2 uv = vUv;
  vec2 uv_orig = vUvOriginal;
  float rad = vRadius;
  float ang = vAngle;
  float corr = uTexSize.xy*texsize_noise_lq.zw;
vec2 uv1 = (uv_orig-.5)*uAspect.xy;
uv1 = multiply(uv1,mat2(q9,q10,-q10,q9));
uv1 *= uAspect.yx;
float h1 = 3;
float k1 = 1;
float z = h1/abs(uv1.y);
rs.x = uv1.x * z * k1;
rs.y = z *k1 / 2.0;
rs0 = rs;
rs *=1;
rs = multiply(mat2(q5,q6,-q6,q5),rs);
rs += vec2 (q7,q8);
float mod = sin((uv1-q12)*q27);
ret1 = GetBlur1(fract(rs / 12.0));
ret = ret1 * 32.0/z
+ q22*sqrt(z) / 4.0*mod * GetPixel(4.0 * ret1/z+uv1 / 2.0/(.5+abs(uv1.y))+vec2(q5, 0.0 ));
  fragColor = vec4(ret, 1.0);
}

